import java.util.*;
import java.util.function.IntUnaryOperator;

public class Main {
    static class RootContext {
        private static final ThreadLocal<String> XID = new ThreadLocal<>();
        static void bind(String xid) { XID.set(xid); }
        static String xid() { return XID.get(); }
        static void clear() { XID.remove(); }
    }

    static class Database {
        private final Map<String, Integer> rows = new LinkedHashMap<>();
        Database stock(int value) { rows.put("stock:sku1", value); return this; }
        Database account(int value) { rows.put("account:u1", value); return this; }
        int get(String key) { return rows.get(key); }
        void put(String key, int value) { rows.put(key, value); }
        String snapshot() { return rows.toString(); }
    }

    static class UndoLog {
        final long branchId;
        final String xid;
        final String rowKey;
        final int beforeImage;
        final int afterImage;
        UndoLog(long branchId, String xid, String rowKey, int beforeImage, int afterImage) {
            this.branchId = branchId;
            this.xid = xid;
            this.rowKey = rowKey;
            this.beforeImage = beforeImage;
            this.afterImage = afterImage;
        }
    }

    static class Branch {
        final long id;
        final String xid;
        final ResourceManager rm;
        final String rowKey;
        Branch(long id, String xid, ResourceManager rm, String rowKey) {
            this.id = id;
            this.xid = xid;
            this.rm = rm;
            this.rowKey = rowKey;
        }
    }

    static class TransactionCoordinator {
        private long xidSeq;
        private long branchSeq;
        private final Map<String, List<Branch>> branches = new LinkedHashMap<>();
        private final Map<String, String> globalLocks = new LinkedHashMap<>();

        String begin() { return "xid-" + (++xidSeq); }

        long registerBranch(String xid, ResourceManager rm, String rowKey) {
            String owner = globalLocks.get(rowKey);
            if (owner != null && !owner.equals(xid)) {
                throw new IllegalStateException("global lock conflict: " + rowKey);
            }
            globalLocks.put(rowKey, xid);
            long branchId = ++branchSeq;
            branches.computeIfAbsent(xid, k -> new ArrayList<>()).add(new Branch(branchId, xid, rm, rowKey));
            return branchId;
        }

        void globalCommit(String xid) {
            for (ResourceManager rm : participants(xid)) rm.commit(xid);
            release(xid);
        }

        void globalRollback(String xid) {
            for (ResourceManager rm : participants(xid)) rm.rollback(xid);
            release(xid);
        }

        int lockCount() { return globalLocks.size(); }

        private List<ResourceManager> participants(String xid) {
            LinkedHashSet<ResourceManager> rms = new LinkedHashSet<>();
            for (Branch branch : branches.getOrDefault(xid, List.of())) rms.add(branch.rm);
            return new ArrayList<>(rms);
        }

        private void release(String xid) {
            globalLocks.entrySet().removeIf(e -> e.getValue().equals(xid));
            branches.remove(xid);
        }
    }

    static class ResourceManager {
        private final String name;
        private final Database db;
        private final TransactionCoordinator tc;
        private final List<UndoLog> undoLogs = new ArrayList<>();

        ResourceManager(String name, Database db, TransactionCoordinator tc) {
            this.name = name;
            this.db = db;
            this.tc = tc;
        }

        void update(String rowKey, IntUnaryOperator operation) {
            String xid = RootContext.xid();
            if (xid == null) throw new IllegalStateException("missing XID in " + name);
            long branchId = tc.registerBranch(xid, this, rowKey);
            int before = db.get(rowKey);
            int after = operation.applyAsInt(before);
            db.put(rowKey, after);
            undoLogs.add(new UndoLog(branchId, xid, rowKey, before, after));
        }

        void commit(String xid) {
            undoLogs.removeIf(log -> log.xid.equals(xid));
        }

        void rollback(String xid) {
            ListIterator<UndoLog> it = undoLogs.listIterator(undoLogs.size());
            while (it.hasPrevious()) {
                UndoLog log = it.previous();
                if (!log.xid.equals(xid)) continue;
                int current = db.get(log.rowKey);
                if (current != log.afterImage) {
                    throw new IllegalStateException("dirty write detected on " + log.rowKey);
                }
                db.put(log.rowKey, log.beforeImage);
                it.remove();
            }
        }

        int undoSize() { return undoLogs.size(); }
    }

    static Database newDb() { return new Database().stock(10).account(100); }

    static void rollbackCase() {
        Database db = newDb();
        TransactionCoordinator tc = new TransactionCoordinator();
        ResourceManager stock = new ResourceManager("stock", db, tc);
        ResourceManager account = new ResourceManager("account", db, tc);
        String xid = tc.begin();
        RootContext.bind(xid);
        try {
            stock.update("stock:sku1", v -> v - 2);
            account.update("account:u1", v -> v - 30);
            throw new RuntimeException("account service timeout");
        } catch (RuntimeException ex) {
            tc.globalRollback(xid);
        } finally {
            RootContext.clear();
        }
        System.out.println("rollback db=" + db.snapshot() + ", undo=" + (stock.undoSize() + account.undoSize()) + ", locks=" + tc.lockCount());
        assert db.snapshot().equals("{stock:sku1=10, account:u1=100}");
        assert tc.lockCount() == 0;
    }

    static void commitCase() {
        Database db = newDb();
        TransactionCoordinator tc = new TransactionCoordinator();
        ResourceManager stock = new ResourceManager("stock", db, tc);
        String xid = tc.begin();
        RootContext.bind(xid);
        try {
            stock.update("stock:sku1", v -> v - 1);
            tc.globalCommit(xid);
        } finally {
            RootContext.clear();
        }
        System.out.println("commit db=" + db.snapshot() + ", undo=" + stock.undoSize() + ", locks=" + tc.lockCount());
        assert db.snapshot().equals("{stock:sku1=9, account:u1=100}");
    }

    static void dirtyWriteCase() {
        Database db = newDb();
        TransactionCoordinator tc = new TransactionCoordinator();
        ResourceManager stock = new ResourceManager("stock", db, tc);
        String xid = tc.begin();
        RootContext.bind(xid);
        boolean dirtyWriteDetected = false;
        try {
            stock.update("stock:sku1", v -> v - 3);
            db.put("stock:sku1", 0); // bypass Seata and break after image validation
            tc.globalRollback(xid);
        } catch (IllegalStateException ex) {
            dirtyWriteDetected = ex.getMessage().contains("dirty write");
        } finally {
            RootContext.clear();
        }
        System.out.println("dirtyWriteDetected=" + dirtyWriteDetected + ", lockedRows=" + tc.lockCount());
        assert dirtyWriteDetected;
        assert tc.lockCount() == 1;
    }

    public static void main(String[] args) {
        rollbackCase();
        commitCase();
        dirtyWriteCase();
    }
}
